import { apiRequest } from "../../lib/apiClient.js";

/**
 * @typedef {"pending_approval" | "approved" | "rejected"} RequisitionStatus
 * New requisitions go straight to "pending_approval"; there is no draft status.
 *
 * @typedef {Object} RequisitionListItem
 * @property {string} id
 * @property {string} requisitionNumber   Generated by the backend.
 * @property {string} requestDate         ISO date.
 * @property {{ id: string, displayName: string }} requestedBy
 * @property {string | null} departmentName
 * @property {string | null} itemsSummary
 * @property {string | null} estimatedAmount  Decimal string.
 * @property {"high" | "medium" | "low"} priority
 * @property {RequisitionStatus} status
 *
 * @typedef {Object} RequisitionCreateRequest
 * @property {string} title
 * @property {string} departmentId
 * @property {string} priority
 * @property {string} requiredDate
 * @property {Array<{ description: string, quantity: string, unitId: string, estimatedCost: string }>} items
 * @property {string} justification
 * @property {string} approverId
 *
 * @typedef {RequisitionListItem & {
 *   title: string, requiredDate: string | null,
 *   approver: { id: string, displayName: string } | null,
 *   justification: string | null,
 *   items: Array<{ description: string, quantity: string, unitLabel: string | null, estimatedCost: string }>,
 *   purchaseOrder: { id: string, orderNumber: string } | null,
 *   pendingApproval: { id: string, version: number } | null,
 *   approvalHistory: Array<{ id: string, decision: "approved" | "rejected", decidedBy: { id: string, displayName: string } | null,
 *     decidedAt: string, comment: string | null }>,
 * }} RequisitionDetail
 * `pendingApproval` is set while an approval is pending; the decision goes through the approvals endpoint, which enforces who may decide.
 */

/** PROPOSED: GET /procurement/purchase-requisitions/{id} → RequisitionDetail */
export function getPurchaseRequisition(id, signal) {
  return apiRequest(`/procurement/purchase-requisitions/${encodeURIComponent(id)}`, { signal });
}

/**
 * PROPOSED: GET /procurement/purchase-requisitions
 * `search` is a case-insensitive substring match on requisition number, title, department name, and requester display name.
 * `requisitionNumber`, `departmentId`, and `requestedById` remain optional exact/partial filters for existing callers.
 */
export function listPurchaseRequisitions(
  { page, pageSize, status, search, requisitionNumber, departmentId, requestedById },
  signal,
) {
  return apiRequest("/procurement/purchase-requisitions", {
    query: { page, pageSize, status, search, requisitionNumber, departmentId, requestedById },
    signal,
  });
}

/** PROPOSED: POST /procurement/purchase-requisitions (submitted for approval) */
export function createPurchaseRequisition(payload, { idempotencyKey }) {
  return apiRequest("/procurement/purchase-requisitions", { method: "POST", body: payload, idempotencyKey });
}
